class Push::NotificationJob < ApplicationJob
  include NotificationsHelper
  include Rails.application.routes.url_helpers

  queue_as :backend

  discard_on ActiveJob::DeserializationError

  def perform(notification)
    notification.push(
      title: notification_title(notification),
      body: notification_body(notification),
      url: card_path(notification.card, script_name: notification.account.slug),
      icon: "/app-icon-192.png",
      badge: "/app-icon-192.png",
      tag: notification.card_id
    )
  end
end
--- app/controllers/users/push_subscriptions_controller.rb
class Users::PushSubscriptionsController < ApplicationController
  wrap_parameters :push_subscription, include: %i[ endpoint p256dh_key auth_key ]

  before_action :set_user
  before_action :ensure_current_user
  before_action :set_subscription, only: :destroy

  def create
    @subscription = @user.push_subscriptions.find_or_initialize_by(endpoint: subscription_params[:endpoint])
    @subscription.update!(subscription_params.merge(user_agent: request.user_agent&.truncate(255)))

    respond_to do |format|
      format.html { redirect_to notifications_settings_path, notice: "Push notifications turned on" }
      format.json { render json: { id: @subscription.id }, status: :created }
    end
  end

  def destroy
    @subscription.destroy

    respond_to do |format|
      format.html { redirect_to notifications_settings_path, notice: "Push notifications turned off" }
      format.json { head :no_content }
    end
  end

  private
    def set_user
      @user = Current.account.users.find(params[:user_id])
    end

    def ensure_current_user
      head :forbidden unless @user == Current.user
    end

    def set_subscription
      @subscription = @user.push_subscriptions.find(params[:id])
    end

    def subscription_params
      params.expect(push_subscription: %i[ endpoint p256dh_key auth_key ])
    end
end
